import PropTypes from 'prop-types';
import React from 'react';
import ReviewLinkAccount from '../review-link/review-link-account';
import ReviewLinkOrder from '../review-link/vendor/review-link-order';
import { Route, Routes, useLocation } from 'react-router-dom';
import ErrorNotification from '../stratosphere-notifications/error-notification';
import getStratosphereErrorPaths from '../stratosphere-error-paths/get-stratosphere-error-paths';
// import { stringifyJson } from '../shared/utils';
const StratosphereApp = ({ useToast, local, i18n }) => {

  const getDecodedData = () => {
    const encodedData = new URLSearchParams(useLocation().search).get('data');
    const decodedData = encodedData ? JSON.parse(decodeURIComponent(encodedData)) : {};
    console.debug('getDecodedData : ', decodedData);
    return decodedData;
  };

  const errorPaths = getStratosphereErrorPaths();
  const partner = ':partnerId/';

  return (
    <Routes>
      <Route path="vendor/:partnerId/:linkToken" element={<ReviewLinkOrder local={local} useToast={useToast} />} />
      <Route path=":partnerId" element={<ReviewLinkAccount local={local} useToast={useToast} />} />
      <Route path={partner + errorPaths.systemError()} element={<ErrorNotification local={local} i18n={i18n} type="general-error" />} />
      <Route path={partner + errorPaths.tokenError()} element={<ErrorNotification local={local} type="token-error" />} />
      <Route path={partner + errorPaths.exportError()} element={<ErrorNotification local={local} type="export-error" />} />
      <Route path={partner + errorPaths.error()} element={<ErrorNotification local={local} type="general-error" />} />
      <Route path={partner + errorPaths.orderError()} element={<ErrorNotification local={local} type="general-error" />} />
      <Route path={partner + errorPaths.systemError()} element={<ErrorNotification local={local} type="general-error" />} />
      <Route path={partner + errorPaths.needAssistance()} element={<ErrorNotification local={local} type="need-assistance" />} />
      <Route path={partner + errorPaths.alreadyLinked() + "/*"} element={<ErrorNotification accountDetails={getDecodedData()} local={local} type="already-linked" />} />
    </Routes>
  );
};

StratosphereApp.propTypes = {
  useToast: PropTypes.func.isRequired,
  local: PropTypes.func.isRequired
};

export default StratosphereApp;
